const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    additional_context: body.additional_context || null,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT + Validate').first().json;
const projectRows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
if (projectRows.length === 0) return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe', request_id: sess.request_id }}];
const project = projectRows[0];
const briefingRows = $input.all().map(i => i.json).filter(b => b && b.summary);
const briefing = briefingRows[0] || null;

const city = (project.location_city || '').toLowerCase().trim();
const knownSlugs = ['madrid','barcelona','valencia','sevilla','bilbao'];
const slug = knownSlugs.includes(city) ? city : null;
if (!slug) {
  return [{ json: { _warn: 'MUNICIPIO_NOT_IN_TOP5', _status: 200, _details: 'Municipio "' + project.location_city + '" no esta en el top 5 con reglas pre-cargadas. Use agent_regulatory para lookup live.', municipio_solicitado: project.location_city, top5_disponibles: knownSlugs, request_id: sess.request_id, project_id: project.id, tenant_id: sess.tenant_id }}];
}
return [{ json: {
  user_id: sess.user_id,
  tenant_id: sess.tenant_id,
  project_id: project.id,
  request_id: sess.request_id,
  municipio_slug: slug,
  project: {
    id: project.id,
    name: project.name,
    project_type: project.project_type,
    property_type: project.property_type,
    property_area_m2: project.property_area_m2,
    location_city: project.location_city,
    current_phase: project.current_phase,
    budget_target: project.budget_target,
    metadata: project.metadata || {}
  },
  briefing: briefing ? { summary: briefing.summary, client_needs: briefing.client_needs, constraints: briefing.constraints } : null,
  additional_context: sess.additional_context
}}];

const ctx = $('Resolve Municipio').first().json;
const rules = $input.all().map(i => i.json).filter(r => r && r.rule_key);
if (rules.length === 0) {
  return [{ json: { _error: 'NO_RULES_FOUND', _status: 500, _details: 'No hay reglas para ' + ctx.municipio_slug + '. Migracion 077 sin aplicar?', request_id: ctx.request_id }}];
}

const project = ctx.project;
const briefing = ctx.briefing;

// Mapping BD project_type -> PGOU vocabulary (mas granular). Inclusive.
const pType = project.project_type || 'otro';
const pgouCandidates = {
  reforma_integral: ['reforma','rehabilitacion','any'],
  redistribucion:   ['reforma','any'],
  cambio_uso:       ['cambio_uso','rehabilitacion','any'],
  adecuacion:       ['reforma','any'],
  apoyo_tecnico:    ['any'],
  otro:             ['any']
}[pType] || ['any'];
const preFiltered = rules.filter(r => {
  const at = r.applies_to || {};
  if (!at.project_type) return true;
  if (Array.isArray(at.project_type)) {
    return at.project_type.some(t => pgouCandidates.includes(t)) || at.project_type.includes('any');
  }
  return pgouCandidates.includes(at.project_type) || at.project_type === 'any';
});

const rulesText = preFiltered.map(function(r, idx) {
  return (idx+1) + '. [' + r.rule_category + '/' + r.severity + '] ' + r.rule_title +
         '\n   key: ' + r.rule_key +
         '\n   descripcion: ' + r.rule_description.slice(0, 350) +
         '\n   normativa: ' + (r.normative_reference || '-') +
         '\n   triggers: ' + JSON.stringify(r.triggers || {}) +
         '\n   licencia: ' + (r.license_implication || '-');
}).join('\n\n');

const systemPrompt = 'Eres agent_municipal_precheck. Cruzas un proyecto contra reglas PGOU de un municipio. Tu trabajo: decidir cuales REALMENTE aplican.\n\nCriterios:\n- Usa los "triggers" de cada regla y el contexto del proyecto para juzgar aplicabilidad.\n- NO inventes reglas. Solo trabajas con las que te paso.\n- Si los triggers no se pueden evaluar con la info del proyecto, marca la regla con applicability="verificar".\n\nOUTPUT JSON estricto:\n{\n  "applicable_rules": [\n    { "rule_key": "...", "applicability": "si"|"no"|"verificar", "razon": "frase corta", "impacto": "critico|importante|info" }\n  ],\n  "recommended_license": "comunicacion_previa|declaracion_responsable|licencia_obra_menor|licencia_obra_mayor|indeterminado",\n  "recommended_license_reasoning": "1-2 frases",\n  "blockers": [ "cosas que paralizan licencia hasta resolverlas (ITE caducada, amianto, etc)" ],\n  "pitfalls_aggregated": [ "errores comunes que afectan a este proyecto" ],\n  "summary_for_architect": "3-5 frases. Espanol. Que tiene que hacer YA y que verificar.",\n  "next_steps": [ "accion 1", "accion 2", "accion 3" ]\n}';

const projectSummary = 'PROYECTO: ' + project.name + '\n' +
  '- Tipo: ' + (project.project_type || '?') + '\n' +
  '- Propiedad: ' + (project.property_type || '?') + ', ' + (project.property_area_m2 || '?') + ' m2\n' +
  '- Municipio: ' + project.location_city + '\n' +
  '- Fase actual: ' + project.current_phase + '\n' +
  '- Budget: ' + (project.budget_target || '?') + ' EUR\n' +
  '- Metadata: ' + JSON.stringify(project.metadata || {}).slice(0, 400);

const briefingSummary = briefing ?
  ('\n\nBRIEFING:\n- summary: ' + (briefing.summary || '').slice(0, 400) +
   '\n- needs: ' + (typeof briefing.client_needs === 'object' ? JSON.stringify(briefing.client_needs).slice(0, 300) : (briefing.client_needs || '').slice(0, 300)) +
   '\n- constraints: ' + (typeof briefing.constraints === 'object' ? JSON.stringify(briefing.constraints).slice(0, 300) : (briefing.constraints || '').slice(0, 300)))
  : '\n\nBRIEFING: (sin briefing)';

const additional = ctx.additional_context ? '\n\nCONTEXTO ADICIONAL: ' + ctx.additional_context.slice(0, 500) : '';

const userPrompt = projectSummary + briefingSummary + additional +
  '\n\nREGLAS PGOU CANDIDATAS (' + preFiltered.length + ' filtradas de ' + rules.length + '):\n' + rulesText +
  '\n\nTAREA: para cada regla, decide si aplica (si/no/verificar) y por que. Luego sintetiza la propuesta de licencia, blockers, pitfalls y next_steps.';

return [{ json: {
  user_id: ctx.user_id,
  tenant_id: ctx.tenant_id,
  project_id: ctx.project_id,
  request_id: ctx.request_id,
  municipio_slug: ctx.municipio_slug,
  rules_total: rules.length,
  rules_prefiltered: preFiltered.length,
  prefiltered_keys: preFiltered.map(r => r.rule_key),
  llm_payload: {
    model: 'gpt-4o',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.1,
    max_tokens: 2200,
    response_format: { type: 'json_object' }
  }
}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id }}];
}
const usage = llm?.usage || {};

const applicableRules = Array.isArray(parsed.applicable_rules) ? parsed.applicable_rules : [];
const applicableKeys = applicableRules.filter(r => r.applicability === 'si').map(r => r.rule_key);
const verificarKeys = applicableRules.filter(r => r.applicability === 'verificar').map(r => r.rule_key);

const validLicenses = ['comunicacion_previa','declaracion_responsable','licencia_obra_menor','licencia_obra_mayor','indeterminado'];
const recommendedLicense = validLicenses.includes(parsed.recommended_license) ? parsed.recommended_license : 'indeterminado';

return [{ json: {
  user_id: built.user_id,
  tenant_id: built.tenant_id,
  project_id: built.project_id,
  request_id: built.request_id,
  municipio_slug: built.municipio_slug,
  output: {
    municipio: built.municipio_slug,
    rules_total_in_db: built.rules_total,
    rules_prefiltered: built.rules_prefiltered,
    rules_applicable_count: applicableKeys.length,
    rules_verify_count: verificarKeys.length,
    applicable_rules: applicableRules,
    recommended_license: recommendedLicense,
    recommended_license_reasoning: parsed.recommended_license_reasoning || null,
    blockers: Array.isArray(parsed.blockers) ? parsed.blockers : [],
    pitfalls_aggregated: Array.isArray(parsed.pitfalls_aggregated) ? parsed.pitfalls_aggregated : [],
    summary_for_architect: parsed.summary_for_architect || null,
    next_steps: Array.isArray(parsed.next_steps) ? parsed.next_steps : []
  },
  model: llm?.model || 'gpt-4o',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

const f = $('Format Output').first().json;
const save = $('Save Precheck').isExecuted ? ($('Save Precheck').first()?.json || {}) : {};
return [{ json: {
  data: {
    precheck_id: save.id || null,
    project_id: f.project_id,
    municipio: f.municipio_slug,
    created_at: save.created_at || null,
    output: f.output
  },
  meta: {
    request_id: f.request_id,
    model: f.model,
    tokens_in: f.tokens_in,
    tokens_out: f.tokens_out,
    eu_ai_act: 'pre-check informativo, no sustituye agent_regulatory ni decision humana'
  }
}}];
